def factor(p):
    """距120日高点：收盘价除以过去120日最高收盘价，越接近1说明价格越强势。"""
    c = p["close"]
    hi = c.rolling(120, min_periods=90).max()
    hi = hi.where(hi > 0)  # 避免除以零
    return (c / hi).replace([np.inf, -np.inf], np.nan)

def factor(p):
    """隔夜收益：过去20日每日开盘价相对前一日收盘价的对数收益之和，反映隔夜情绪。"""
    prev_close = p["close"].shift(1)
    ratio = p["open"] / prev_close.where(prev_close > 0)  # 避免除以零
    overnight = np.log(ratio).replace([np.inf, -np.inf], np.nan)
    return overnight.rolling(20, min_periods=15).sum()

def factor(p):
    """彩票效应：过去20日最大单日收益越大，说明投机情绪越强，未来收益往往偏低。"""
    close = p["close"]
    ret = close / close.shift(1) - 1            # 每日收益
    f = ret.rolling(20, min_periods=15).max()   # 20日内最大单日收益
    return f.replace([np.inf, -np.inf], np.nan)

def factor(p):
    """量价配合：收益与换手率的滚动相关系数，放量上涨越明显说明投机氛围越重，未来收益偏低。"""
    ret = p["close"].pct_change(fill_method=None)   # 每日收益
    turn = p["turnover"]                            # 每日换手率
    f = ret.rolling(60, min_periods=45).corr(turn)  # 收益与换手率的60日相关
    return f.replace([np.inf, -np.inf], np.nan)

def factor(p):
    """净股票发行：总股本一年内的变化，股本扩张意味着供给增加，未来收益偏低。"""
    ts = p["total_share"].where(p["total_share"] > 0)  # 去掉缺失和异常值
    f = np.log(ts / ts.shift(252))                      # 一年（252个交易日）股本变化
    return f.replace([np.inf, -np.inf], np.nan)

def factor(p):
    """收盘位置：收盘价在当日高低区间中位置的平均值，偏高说明尾盘买盘过热，未来收益偏低。"""
    rng = (p["high"] - p["low"]).replace(0, np.nan)   # 当日振幅，避免除0
    clv = (p["close"] - p["low"]) / rng               # 收盘价在当日区间中的位置（0~1）
    f = clv.rolling(20, min_periods=15).mean()         # 20日平均收盘位置
    return f.replace([np.inf, -np.inf], np.nan)

def factor(p):
    """毛利率变化：最新公告的毛利率相对约两个季度（120个交易日）前的变化。
    毛利率提升说明产品定价能力和竞争地位改善，基本面变好的公司未来收益更高。"""
    gm = p["gross_margin"]
    return gm - gm.shift(120)
